#!/bin/bash
# crear-lab7.sh — crea el escenario Killercoda "lab7-eldia-condortech" (Módulo 4 · Clase 13)
# Uso (macOS o Linux): cd <tu-repo-killercoda> && bash crear-lab7.sh
# Prerrequisitos ANTES de correrlo: estar dentro del repositorio git conectado a killercoda.com/cruzgio
#   y no tener una carpeta lab7-eldia-condortech previa (si existe, se reemplaza).
set -e
[ -d .git ] || { echo "Corre este script dentro de tu repositorio git de Killercoda."; exit 1; }
rm -rf lab7-eldia-condortech
TMP=$(mktemp)
sed -n '/^__PAYLOAD__$/,$p' "$0" | tail -n +2 | base64 -d > "$TMP"
SUM=$( (shasum -a 256 "$TMP" 2>/dev/null || sha256sum "$TMP") | cut -d' ' -f1)
[ "$SUM" = "b3b9c24acf95c0ca7846a3d696acccc139b0ef352b7175084fd36acd7670e08f" ] || { echo "Integridad fallida"; exit 1; }
tar xzf "$TMP" && rm -f "$TMP"
chmod +x lab7-eldia-condortech/background.sh lab7-eldia-condortech/assets/*
echo "✔ Escenario creado en ./lab7-eldia-condortech"
echo "Ahora publícalo con:"
echo '  git add -A && git commit -m "Lab 7 EL DIA - Clase 13" && git push'
echo "URL esperada: https://killercoda.com/cruzgio/scenario/lab7-eldia-condortech"
exit 0
__PAYLOAD__

